		path: "src/main/java/net/worldforge/api/combat/AttributeInfo.java",
		content: "package net.worldforge.api.combat;\n\nimport java.util.Objects;\n\n/**\n * Vanilla (or datapack) attribute id from the official attribute registry.\n */\npublic final class AttributeInfo {\n    private final String id;\n\n    public AttributeInfo(String id) {\n        this.id = Objects.requireNonNull(id);\n    }\n\n    public String id() {\n        return id;\n    }\n}\n"
